from taf.internal.rpc.pyro.pyro_server import PyroServerRunner


class MTKPYROServerRunner(PyroServerRunner):

    def __init__(self, hostname, port, server_dir=None,
                 ssh_user_name=None, ssh_password=None, python_path=None, packages=None, **kwargs):
        super(MTKPYROServerRunner, self).__init__(hostname=hostname,
                                                  port=port,
                                                  server_dir=server_dir,
                                                  ssh_user_name=ssh_user_name,
                                                  ssh_password=ssh_password,
                                                  python_path=python_path,
                                                  packages=packages,
                                                  **kwargs)

    def _get_startup_log_file_existence_check_tries(self):
        return 10

    def _get_startup_log_content_check_tries(self):
        return 10
